&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;span data-ccp-charstyle=&quot;citation-6&quot; data-ccp-charstyle-defn=&quot;{&amp;quot;ObjectId&amp;quot;:&amp;quot;0a950e52-e491-55c3-8b16-6fa80c2fcfc6|1&amp;quot;,&amp;quot;ClassId&amp;quot;:1073872969,&amp;quot;Properties&amp;quot;:[201342446,&amp;quot;1&amp;quot;,201342447,&amp;quot;5&amp;quot;,201342448,&amp;quot;3&amp;quot;,201342449,&amp;quot;1&amp;quot;,469777841,&amp;quot;Aptos&amp;quot;,469777842,&amp;quot;Arial&amp;quot;,469777843,&amp;quot;ＭＳ 明朝&amp;quot;,469777844,&amp;quot;Aptos&amp;quot;,201341986,&amp;quot;1&amp;quot;,469769226,&amp;quot;Aptos,Arial,ＭＳ 明朝&amp;quot;,268442635,&amp;quot;24&amp;quot;,469775450,&amp;quot;citation-6&amp;quot;,201340122,&amp;quot;1&amp;quot;,134233614,&amp;quot;true&amp;quot;,469778129,&amp;quot;citation-6&amp;quot;,335572020,&amp;quot;1&amp;quot;,469778324,&amp;quot;Default Paragraph Font&amp;quot;]}&quot;&gt;Engineering Proficiency:&lt;/span&gt;&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;span data-ccp-charstyle=&quot;citation-6&quot;&gt;&amp;nbsp;Mastery of Python and&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-charstyle=&quot;citation-6&quot;&gt;PyTorch&lt;/span&gt;&lt;span data-ccp-charstyle=&quot;citation-6&quot;&gt;, e&lt;/span&gt;xperience with distributed training frameworks and large-scale distributed data processing pipelines and tools.&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
