&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp; Experience doing full chip floor planning and integration.&amp;nbsp;&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
